import{_ as l,b as p,c as e,g as o}from"./chunks/framework.86O3EbG5.js";const s=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"articles/artificial-intelligence/books/AI-modern-approach-homework/2.md","filePath":"articles/artificial-intelligence/books/AI-modern-approach-homework/2.md"}'),a={name:"articles/artificial-intelligence/books/AI-modern-approach-homework/2.md"};function t(r,i,n,d,h,_){return p(),e("div",null,[...i[0]||(i[0]=[o('<h2 id="_2-1-智能体与环境" tabindex="-1">2.1 智能体与环境</h2><ol><li>判断题：任何通过传感器感知环境并通过执行器作用于环境的实体都可被称为智能体。 对</li><li>判断题：智能体的感知序列仅包含当前时刻的感知，不包含历史信息。 错</li><li>判断题：智能体函数将完整感知序列映射为动作，是抽象的数学描述。 对</li><li>判断题：智能体程序实现智能体函数，但两者并非同一概念。 对。智能体=架构+程序。智能体函数是其中的一部分。</li><li>判断题：在真空吸尘器世界中，智能体只能感知当前方格是否脏污，无法知道地图布局。 对</li><li>判断题：任务环境的四要素是性能度量、外部环境、执行器和传感器。 对</li><li>判断题：环境维度如确定性、可观测性、单智能体或多智能体不会影响智能体设计。 错</li><li>判断题：智能体在完全可观测环境里无需维护内部状态。 对</li><li>判断题：执行器只负责物理动作，不参与决策。 对</li><li>判断题：智能体与环境的耦合关系决定了其行为效果。 对</li></ol><h2 id="_2-2-理性" tabindex="-1">2.2 理性</h2><ol><li><p>判断题：理性智能体在任何情况下都会选择期望性能度量最大的动作。 错</p></li><li><p>判断题：理性依赖于性能度量、先验知识、可行动作和感知序列四要素。 对</p></li><li><p>判断题：全知智能体能够预知所有动作结果，现实中通常不可行。 对</p></li><li><p>判断题：在真空吸尘器示例中，若性能度量改为惩罚每步移动，则简单“脏则吸、否则移”仍理性。</p></li><li><p>判断题：理性智能体必须显式存储整个感知历史以做出决策。 错</p></li><li><p>判断题：结果主义评估智能体行为只看最终结果，不关心过程。</p></li></ol><p>结果主义并不等于只关心结果，而是根据整体效用来评估动作。(动作就是过程)。性能度量并非只能评估最终结果，而是可以任意定义（包括对过程的惩罚和奖励）</p><ol start="7"><li>判断题：性能度量由设计者设定，智能体自身没有偏好。 对</li><li>判断题：在部分可观测环境中，理性智能体需维护对世界可能状态的信念。 对</li><li>判断题：学习能力对理性智能体并非必需，但可以提升长期表现。 对</li><li>判断题：理性概念同时涵盖“做正确的事”和“高效地做”两层含义。 错</li></ol><h2 id="_2-3-环境的本质" tabindex="-1">2.3 环境的本质</h2><ol><li><p>判断题：确定性环境下一动作的成功与否可完全由当前状态确定。 对，因为环境不会在智能体做决策的过程中变化</p></li><li><p>判断题：动态环境状态随时间变化，与智能体动作无关。 错，智能体的动作会导致环境变化，在加入了时间的维度后，智能体的动作可能和智能体预期的结果不一致</p></li><li><p>判断题：离散环境中的状态数量有限，连续环境则无限。 对，时间是连续的，方位是离散的。</p></li><li><p>判断题：回合式环境在智能体采取动作后立即终止。</p></li><li><p>判断题：多智能体环境中的智能体决策无需考虑其他智能体行为。 错，博弈也可以算作一种多智能体环境，其核心算法是min-max</p></li><li><p>判断题：部分可观测马尔可夫决策过程（POMDP）是处理不确定性与部分信息的统一框架。 对</p></li><li><p>判断题：未知环境指智能体对转移模型和奖励函数均无先验。 对</p></li><li><p>判断题：连续状态空间环境下，智能体通常采用函数近似方法。 对</p></li><li><p>判断题：在静态环境里，智能体可一次性规划完成任务而无需在线修正。 对</p></li><li><p>判断题：随机博弈属于非合作多智能体环境的一种形式。 对</p></li></ol><h2 id="_2-4-智能体的结构" tabindex="-1">2.4 智能体的结构</h2><ol><li>判断题：智能体=架构+程序，二者必须匹配。 对</li><li>判断题：架构负责执行动作，程序只负责感知输入。 架构是智能体的物理载体，负责获取感知和执行、程序既负责感知输入的处理、也负责生成动作的输出。</li><li>判断题：表驱动型智能体通过查表直接映射感知序列到动作。 对</li><li>判断题：基于模型的智能体维护内部状态以跟踪世界变化。 对</li><li>判断题：目标驱动型智能体的动作旨在达成显式目标。 对</li><li>判断题：效用驱动型智能体追求期望效用最大化。 对</li><li>判断题：反应型智能体无需保存感知历史即可决策。 对</li><li>判断题：所有智能体都必须具备学习能力以适应新环境。 错</li><li>判断题：智能体程序通常以伪代码描述，与具体编程语言无关。 对</li><li>判断题：架构可以是普通 PC，也可以是带多传感器的机器人车辆。 对</li></ol><h2 id="简述简单反射型智能体与基于模型的反射型智能体的核心区别。为什么后者在部分可观测环境中更有优势" tabindex="-1">简述简单反射型智能体与基于模型的反射型智能体的核心区别。为什么后者在部分可观测环境中更有优势？</h2><p>1.什么是简单反射型智能体 2.什么是基于模型的反射型智能体</p><p>1.简单反射型智能体的特点或优势 2.基于模型的反射型智能体的特点或优势</p><p>3.部分可观测环境的特点，需要在部分可观测环境中解决什么问题？</p><h2 id="考虑一个自动恒温器-其性能是保持室温在设定值附近-误差±1度-。请分析该环境的以下属性-并说明理由" tabindex="-1">考虑一个自动恒温器，其性能是保持室温在设定值附近（误差±1度）。请分析该环境的以下属性，并说明理由：</h2><ul><li>完全可观测 or 部分可观测？部分可观测，因为自动恒温器无法知道房屋的门窗是否敞开，当前是不是冬季</li><li>确定性 or 随机性？</li><li>静态 or 动态？ 动态：因为温度是变化的</li><li>离散 or 连续？ 连续：因为温度是连续的</li><li>单智能体 or 多智能体？单智能体</li></ul><h2 id="除书本上的吸尘器世界外-举出一个部分可观测的现实世界环境例子-并解释为什么部分可观测会迫使智能体必须维护内部状态-而不是仅依赖当前感知-。" tabindex="-1">除书本上的吸尘器世界外，举出一个部分可观测的现实世界环境例子，并解释为什么部分可观测会迫使智能体必须维护内部状态（而不是仅依赖当前感知）。</h2><p>1.什么是部分可观测？ 2.</p><h2 id="你设计一个股票交易智能体-性能度量是年度收益率。" tabindex="-1">你设计一个股票交易智能体，性能度量是年度收益率。</h2><p>(a) 如果性能度量仅按收益率（越高越好），可能会产生哪些“合理但不合意”的行为（即钻漏洞）？ 仅仅按照收益率，可能导致智能体买入风险更高的产品，从而让实际收益率下降</p><p>(b) 请提出一种改进的性能度量，以鼓励更稳健的交易行为。 除了按照收益率，还要看股票的波动区间。</p><h2 id="设计一个基于效用的智能体的伪代码框架-不需要具体实现效用函数和转移模型-但要在注释中说明各步骤-。要求体现" tabindex="-1">设计一个基于效用的智能体的伪代码框架（不需要具体实现效用函数和转移模型，但要在注释中说明各步骤）。要求体现：</h2><ul><li>维护信念状态（简化：假设完全可观测，则信念 = 当前状态）</li><li>如何利用效用函数在不确定性下选择动作（写出期望效用计算的概念）</li></ul>',23)])])}const m=l(a,[["render",t]]);export{s as __pageData,m as default};
